from PIL import Image

def analyze(path):
    im = Image.open(path)
    w,h = im.size
    px = im.load()
    # white-ish pixels
    whites = []
    darks = []
    for y in range(h):
        for x in range(w):
            r,g,b = px[x,y][:3]
            if r>200 and g>200 and b>200:
                whites.append((x,y))
            elif r<50 and g<50 and b<50:
                darks.append((x,y))
    def centroid(pts):
        if not pts: return None
        return len(pts), sum(p[0] for p in pts)/len(pts), sum(p[1] for p in pts)/len(pts)
    print(path, "white", centroid(whites), "darkcount", len(darks))

for i in range(11,17):
    analyze(f"/home/robot/captures/wrist_{i:03d}.png")
